function todayView(){let a=S.trainings.filter(x=>weekStart(x.date)===weekStart(today()));return `<header class="top"><div><div class="eyebrow">${dateText(today())}</div><h1>Heute</h1></div><button data-action="settings" aria-label="Einstellungen">${appIcon('settings',19)}</button></header><main class="content">${weightCard()}${nutritionCards(today())}<div class="btnrow">${htmlButton('+ Mahlzeit','meal')}${htmlButton('+ Getränk','drink')}</div><div class="section-title">Heute erfasst</div><section class="card">${nutritionEntries(today())}</section><div class="section-title">Training</div><section class="card"><div class="split"><div><strong>${a.length} ${a.length===1?'Einheit':'Einheiten'} diese Woche</strong><div class="small muted" style="margin-top:5px">Dein Trainingstagebuch</div></div><button class="btn sm secondary" data-action="go:training">Ansehen</button></div></section></main>`}
